INSERT INTO public.reviews (id, source, source_id, url, product_name, content, sentiment, tag, created_at) VALUES (821, 'trustradius', '59_c_2', 'https://www.trustradius.com/reviews/sap-analytics-cloud-2026-03-05-02-27-10', 'SAP Analytics Cloud', 'Cons: There is no easy way to search for a value of a dimension (member) which makes it super hard to select a filter', 0, 'Usability,Features', '2026-06-26 15:58:14.845508');
INSERT INTO public.reviews (id, source, source_id, url, product_name, content, sentiment, tag, created_at) VALUES (822, 'trustradius', '60_p_0', 'https://www.trustradius.com/reviews/sap-analytics-cloud-2025-12-27-10-10-28', 'SAP Analytics Cloud', 'Pros: SAC has well-built integration points with BI data sources, the S/4HANA backend system, and 3rd-party tools to extract and derive meaningful insights from past data.', 1, 'Integration,Features', '2026-06-26 15:58:14.845508');
INSERT INTO public.reviews (id, source, source_id, url, product_name, content, sentiment, tag, created_at) VALUES (823, 'trustradius', '60_p_1', 'https://www.trustradius.com/reviews/sap-analytics-cloud-2025-12-27-10-10-28', 'SAP Analytics Cloud', 'Pros: SAC reports provide an interactive way to analyze data across multiple dimensions, enabling Leaders to see different perspectives before making a decision. This means you don''t have to spend hours doing analysis in different ways to see the actual output for decision-making. SAC provides a single dashboard for multi-dimensional analysis.', 1, 'Performance,Features', '2026-06-26 15:58:14.845508');
INSERT INTO public.reviews (id, source, source_id, url, product_name, content, sentiment, tag, created_at) VALUES (824, 'trustradius', '60_p_2', 'https://www.trustradius.com/reviews/sap-analytics-cloud-2025-12-27-10-10-28', 'SAP Analytics Cloud', 'Pros: Its user-friendly UI and dashboard-based reports make it easy for a commoner to use. Its accessibility across multiple devices, such as mobile/ laptop, and tablet, makes it an on-the-go decision-making tool, available anywhere and everywhere.', 1, 'Usability,Features', '2026-06-26 15:58:14.845508');
INSERT INTO public.reviews (id, source, source_id, url, product_name, content, sentiment, tag, created_at) VALUES (825, 'trustradius', '60_c_0', 'https://www.trustradius.com/reviews/sap-analytics-cloud-2025-12-27-10-10-28', 'SAP Analytics Cloud', 'Cons: Integration with 3rd party system might require not-so-easy configurations and set-up that might be time taking and not plug-and-play kind.', 0, 'Integration,Usability', '2026-06-26 15:58:14.845508');
INSERT INTO public.reviews (id, source, source_id, url, product_name, content, sentiment, tag, created_at) VALUES (826, 'trustradius', '60_c_1', 'https://www.trustradius.com/reviews/sap-analytics-cloud-2025-12-27-10-10-28', 'SAP Analytics Cloud', 'Cons: For very large dataset, the performance issue might be observed that may be a negative as compared to competitor tool''s performance.', 0, 'Performance', '2026-06-26 15:58:14.845508');
INSERT INTO public.reviews (id, source, source_id, url, product_name, content, sentiment, tag, created_at) VALUES (827, 'trustradius', '60_c_2', 'https://www.trustradius.com/reviews/sap-analytics-cloud-2025-12-27-10-10-28', 'SAP Analytics Cloud', 'Cons: While it works seamlessly with HANA and SAP BI dataset, integration with 3rd party systems like Blue Yonder or Oracle Financials might not be efficient when extracting data and creating meaningful insights.', 0, 'Integration,Stability', '2026-06-26 15:58:14.845508');
